// --- GYROID (Superficie Minima Triplamente Periodica) ---

// Lo slider A controlla lo zoom (frequenza)
float scale = A > 0.0 ? (A * 5.0) : 4.0;

// Lo slider B controlla lo spessore della "crosta"
float thickness = B > 0.0 ? B : 0.05;

// Scaliamo lo spazio e aggiungiamo il tempo 't' per far scorrere il labirinto
vec3 q = p * scale + vec3(t, t * 0.5, 0.0);

// La formula esatta del Gyroid
float d = abs(dot(sin(q), cos(q.zxy))) - thickness;

float fudgeFactor = C > 0.0 ? C : 0.5;

// Riduciamo i passi del raggio moltiplicando per il fudge factor
return (d / scale) * fudgeFactor;

