// Fluid energy over the bubble shape
vec3 p = pModel * 5.0;
float distorsione = sin(p.x) * sin(p.y + ubuf.u_time) * sin(p.z);
float energia = sin(length(p) * 3.0 *E+ distorsione * 4.0 *E- ubuf.u_time * 3.0*E);
energia = energia * 0.5 + 0.5;

// u_col2 = dark background, u_col1 = glowing energy (dock colors)
textureCol = mix(ubuf.u_col2, ubuf.u_col1, energia);

